-- Open-world creature damage modifiers: creature_template.DamageModifier (AzerothCore's column and default).
--
-- Since the 2026-09-06 stat-system migration the per-creature damage multiplier lived only in DUNGEON_NORMAL rows of
-- creature_template_difficulty. Open-world maps run on REGULAR_DIFFICULTY (0), which has no row, so no per-creature
-- damage modifier applied outside instances. The core now loads creature_template.DamageModifier (x the rank's
-- Rate.Creature.*.Damage, as AzerothCore) and uses it on every map where the creature has no difficulty row; a
-- difficulty row (instances, battlegrounds) replaces it, so instance damage is unchanged.
--
-- Values assume the creature melee attack-time change (weapon damage x attack time, damage_exp4 per second).
-- Audit of the 11718 templates with a DUNGEON_NORMAL DamageModifier other than 1 and a spawn on a non-instance map:
--   Part B  restore the DUNGEON_NORMAL value      4015 templates (it equals AzerothCore's DamageModifier for the same creature
--           within 10%, or matches a retail MoP Classic 5.5.4 sniff median within 25%, or there is no AzerothCore / retail
--           data and it is 0.2-3, or it brings a level 80-85 Cataclysm normal creature's flat expansion-3 damage column to
--           0.5-1.5x the client NpcDamageByClassExp3 table)
--   Part C  AzerothCore's DamageModifier          1735 templates (one from a retail sniff)
--   Part D  the reference 5.4.8 multiplier        1138 templates whose DUNGEON_NORMAL value is 5+ while the reference 5.4.8
--           data has 3 or less (1124 of them have 1: no row), plus Morgrinn Crackfang (reference 6)
--   no modifier                                   4286 templates (AzerothCore has none, triggers / not selectable, no base
--           damage at the level, retail says none) and 543 more without AzerothCore or retail data (elite city and faction
--           NPCs, bosses, leaders) left at 1 until per-creature retail values are sourced.
-- Templates that are only summoned (no static spawn) are not covered yet.
-- Every statement sets an absolute value, so running the file again changes nothing.

-- Part A: the column, added once.
SET @dmgmod_col := (SELECT COUNT(*) FROM information_schema.COLUMNS
    WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'creature_template' AND COLUMN_NAME = 'DamageModifier');
SET @dmgmod_sql := IF(@dmgmod_col = 0, 'ALTER TABLE `creature_template` ADD COLUMN `DamageModifier` FLOAT NOT NULL DEFAULT 1 AFTER `dmgschool`', 'DO 0');
PREPARE dmgmod_stmt FROM @dmgmod_sql;
EXECUTE dmgmod_stmt;
DEALLOCATE PREPARE dmgmod_stmt;

-- Part B: restore the DUNGEON_NORMAL value (4015 templates).
UPDATE `creature_template` t
JOIN `creature_template_difficulty` d ON d.`id` = t.`entry` AND d.`difficulty` = 'DUNGEON_NORMAL'
SET t.`DamageModifier` = d.`DamageModifier`
WHERE t.`entry` IN (
